    --border: 217.2 32.6% 17.5%;
    --input: 217.2 32.6% 17.5%;
    --ring: 224.3 76.3% 94.1%;
  }
}

@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply bg-background text-foreground;
  }

  html {
    scroll-behavior: smooth;
  }
}

@layer components {
  /* Mobile-first touch optimizations */
  .touch-target {
    @apply min-h-[44px] min-w-[44px];
  }

  .mobile-tap {
    @apply active:scale-95 transition-transform duration-75;
  }

  /* OASIS specific components */
  .oasis-gradient {
    background: linear-gradient(135deg, #06b6d4 0%, #8b5cf6 100%);
  }

  .oasis-glow {
    @apply shadow-glow animate-pulse-glow;
  }

  .revenue-positive {
    @apply text-revenue-positive;
  }

  .revenue-negative {
    @apply text-revenue-negative;
  }

  .revenue-neutral {
    @apply text-revenue-neutral;
  }

  /* Glass morphism effect */
  .glass {
    @apply bg-white/10 backdrop-blur-md border border-white/20;
  }

  .glass-dark {
    @apply bg-black/10 backdrop-blur-md border border-white/10;
  }

  /* Loading states */
  .loading-shimmer {
    background: linear-gradient(90deg, #f0f0f0 25%, #e0e0e0 50%, #f0f0f0 75%);
    background-size: 200% 100%;
    animation: loading-shimmer 1.5s infinite;
  }

  .dark .loading-shimmer {
    background: linear-gradient(90deg, #2a2a2a 25%, #3a3a3a 50%, #2a2a2a 75%);
    background-size: 200% 100%;
  }

  @keyframes loading-shimmer {
    0% {
      background-position: 200% 0;
    }
    100% {
      background-position: -200% 0;
    }
  }

  /* Scrollbar styling */
  .custom-scrollbar::-webkit-scrollbar {
    width: 6px;
  }

  .custom-scrollbar::-webkit-scrollbar-track {
    @apply bg-muted;
  }

  .custom-scrollbar::-webkit-scrollbar-thumb {
    @apply bg-border rounded-full hover:bg-accent;
  }

  /* Focus states */
  .focus-ring {
    @apply focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2;
  }

  /* Revenue counter animation */
  .revenue-counter {
    @apply animate-revenue-counter;
  }
}

@layer utilities {
  .text-balance {
    text-wrap: balance;
  }

  /* Mobile-specific utilities */
  @media (max-width: 768px) {
    .mobile-padding {
      @apply px-4 py-2;
    }

    .mobile-text {
      @apply text-sm leading-relaxed;
    }
  }

  /* Print styles */
  @media print {
    .no-print {
      display: none !important;
    }

    .print-only {
      display: block !important;
    }
  }
}

/* Progressive Web App styles */
@media (display-mode: standalone) {
  body {
    padding-top: env(safe-area-inset-top);
    padding-bottom: env(safe-area-inset-bottom);
  }
}

/* High contrast mode support */
@media (prefers-contrast: high) {
  .glass {
    @apply bg-white border-black;
  }

  .glass-dark {
    @apply bg-black border-white;
  }
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}'''

