stripe_webhook = '''import { headers } from 'next/headers'
import { NextRequest, NextResponse } from 'next/server'
import { stripe } from '@/lib/stripe'
import { createRouteHandlerClient } from '@supabase/auth-helpers-nextjs'
import { cookies } from 'next/headers'
import Stripe from 'stripe'

const endpointSecret = process.env.STRIPE_WEBHOOK_SECRET!

export async function POST(request: NextRequest) {
  const body = await request.text()
  const headersList = headers()
  const sig = headersList.get('stripe-signature')!

  let event: Stripe.Event

  try {
    event = stripe.webhooks.constructEvent(body, sig, endpointSecret)
  } catch (err) {
    console.error('Webhook signature verification failed:', err)
    return NextResponse.json({ error: 'Invalid signature' }, { status: 400 })
  }

  const supabase = createRouteHandlerClient({ cookies })

  try {
    switch (event.type) {
      case 'customer.subscription.created':
      case 'customer.subscription.updated': {
        const subscription = event.data.object as Stripe.Subscription

        // Update user subscription in database
        const { error } = await supabase
          .from('profiles')
          .update({
            subscription_id: subscription.id,
            subscription_status: subscription.status,
            subscription_tier: subscription.items.data[0]?.price.lookup_key || 'pro',
            updated_at: new Date().toISOString(),
          })
          .eq('stripe_customer_id', subscription.customer)

        if (error) {
          console.error('Error updating subscription:', error)
          return NextResponse.json({ error: 'Database update failed' }, { status: 500 })
        }

        // Track revenue event
        const amount = subscription.items.data[0]?.price.unit_amount || 0
        await supabase
          .from('revenue_events')
          .insert({
            event_name: 'subscription_updated',
            event_value: amount / 100, // Convert from cents
            stripe_event_id: event.id,
            metadata: {
              subscription_id: subscription.id,
              customer_id: subscription.customer,
            },
          })

        break
      }

      case 'customer.subscription.deleted': {
        const subscription = event.data.object as Stripe.Subscription

        // Update user subscription status
        const { error } = await supabase
          .from('profiles')
          .update({
            subscription_status: 'canceled',
            subscription_tier: 'free',
            updated_at: new Date().toISOString(),
          })
          .eq('stripe_customer_id', subscription.customer)

        if (error) {
          console.error('Error canceling subscription:', error)
          return NextResponse.json({ error: 'Database update failed' }, { status: 500 })
        }

        break
      }

      case 'invoice.payment_succeeded': {
        const invoice = event.data.object as Stripe.Invoice

        if (invoice.subscription) {
          // Track successful payment
          await supabase
            .from('revenue_events')
            .insert({
              event_name: 'payment_succeeded',
              event_value: (invoice.amount_paid || 0) / 100,
              stripe_event_id: event.id,
              metadata: {
                invoice_id: invoice.id,
                subscription_id: invoice.subscription,
                customer_id: invoice.customer,
              },
            })
        }

        break
      }

      case 'invoice.payment_failed': {
        const invoice = event.data.object as Stripe.Invoice

        // Handle failed payment
        await supabase
          .from('revenue_events')
          .insert({
            event_name: 'payment_failed',
            event_value: (invoice.amount_due || 0) / 100,
            stripe_event_id: event.id,
            metadata: {
              invoice_id: invoice.id,
              subscription_id: invoice.subscription,
              customer_id: invoice.customer,
            },
          })

        break
      }

      default:
        console.log(`Unhandled event type ${event.type}`)
    }

    return NextResponse.json({ received: true })
  } catch (error) {
    console.error('Webhook handler error:', error)
    return NextResponse.json(
      { error: 'Webhook handler failed' },
      { status: 500 }
    )
  }
}'''

