const HF_SPACES_URL = process.env.NEXT_PUBLIC_HF_SPACES_URL || 'https://your-hf-space.hf.space'
const API_TIMEOUT = 30000 // 30 seconds

export interface HFAPIResponse<T = any> {
  success: boolean
  data?: T
  error?: string
  usage?: {
    requests_count: number
    tokens_used: number
    cost: number
  }
}

